package com.eurobuddha.ethwallet;

import com.eurobuddha.minimacore.i18n.Language;
import static com.eurobuddha.minimacore.i18n.R.string.*;

/** Explicit ETH Wallet failures only. Never use for user content, names, addresses or filenames.
 * Reuses Parlons SystemMessages' fixed lookup, literal captures and bounded diagnostic recursion.
 * Generated by adapt-pandamonium-eth-languages.py from localization/eth-errors.json. */
public final class EthMessages {
    private EthMessages() {}
    public static CharSequence error(Throwable error) {
        if (error == null) return Language.msg(l10n_wallet_operation_failed);
        return message(error.getMessage() == null ? error.toString() : error.getMessage());
    }
    public static CharSequence message(String value) { return message(value,0); }
    private static CharSequence message(String value,int depth) {
        if (value == null) return "";
        if (depth >= 8) return value;
        switch(value) {
            case "Node returned no seedrandom — is the node write-enabled?": return Language.msg(l10n_eth_wallet_error_no_seed);
            case "Node returned an all-zero key. Not using it.": return Language.msg(l10n_eth_wallet_error_zero_key);
            case "no decimals() — not an ERC20?": return Language.msg(l10n_eth_wallet_error_no_decimals);
            case "Wallet session changed. Review again.": return Language.msg(l10n_wallet_review_again);
            default: break;
        }
        for(int i=0;i<PATTERNS.length;i++) {
            java.util.regex.Matcher match=PATTERNS[i].matcher(value);
            if(!match.matches())continue;
            Object[] arguments=new Object[match.groupCount()];
            for(int j=0;j<arguments.length;j++) {
                String literal=match.group(j+1);
                arguments[j]=DIAGNOSTIC[i][j] ? message(literal,depth+1) : literal;
            }
            return Language.msg(RESOURCES[i],arguments);
        }
        return value;
    }
    private static final java.util.regex.Pattern[] PATTERNS={
        java.util.regex.Pattern.compile("Node\\ returned\\ a\\ malformed\\ key\\ \\((-?[0-9]+)\\ chars,\\ expected\\ 64\\)\\.\\ Not\\ using\\ it\\."),
        java.util.regex.Pattern.compile("Key\\ derivation\\ failed:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("Refusing\\ to\\ sign:\\ gas\\ price\\ (-?[0-9]+(?:\\.[0-9]+)?)\\ gwei\\ exceeds\\ the\\ (-?[0-9]+(?:\\.[0-9]+)?)\\ gwei\\ safety\\ cap\\.\\ Check\\ your\\ RPC\\ endpoint\\."),
        java.util.regex.Pattern.compile("Refusing\\ to\\ sign:\\ gas\\ limit\\ ((?s:.*))\\ is\\ outside\\ the\\ safe\\ range\\ \\(max\\ (-?[0-9]+)\\)\\.\\ Check\\ your\\ RPC\\ endpoint\\."),
        java.util.regex.Pattern.compile("send\\ failed:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("((?s:.*))\\ failed\\ on\\ all\\ RPCs:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("ETH\\ eth_call\\ build\\ error:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("estimateGas\\ build\\ error:\\ ((?s:.*))")
    };
    private static final int[] RESOURCES={l10n_eth_wallet_error_malformed_key,l10n_eth_wallet_error_derive_failed,l10n_eth_wallet_error_price_cap,l10n_eth_wallet_error_limit_cap,l10n_eth_wallet_error_send_result,l10n_eth_wallet_error_all_rpc,l10n_eth_wallet_error_call_build,l10n_eth_wallet_error_estimate_build};
    private static final boolean[][] DIAGNOSTIC={{false},{false},{false,false},{false,false},{false},{false,false},{false},{false}};
}
